import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'pathslash';
import { loadTypedVoidConfigFile, TYPED_CONFIG_FILE } from './config-loader.ts';
import { validateConfig, type VoidConfig } from './config.ts';

const GENERATED_MARKERS = [
  '// Generated by void migrate.',
  '// Generated from void.json by void migrate.',
  '// Generated by void init.',
];

export function renderVoidConfig(
  config: VoidConfig,
  marker: string = GENERATED_MARKERS[0],
): string {
  return `${marker}\nimport { defineConfig } from 'void/config';\n\nexport default defineConfig(${JSON.stringify(config, null, 2)});\n`;
}

/** Update CLI-owned static config without silently rewriting authored TypeScript. */
export function writeVoidProjectConfig(root: string, config: VoidConfig): void {
  validateConfig(config, TYPED_CONFIG_FILE);
  const path = join(root, TYPED_CONFIG_FILE);
  if (existsSync(path)) {
    const original = readFileSync(path, 'utf8');
    const marker = GENERATED_MARKERS.find((candidate) => original.startsWith(candidate));
    const loaded = validateConfig(loadTypedVoidConfigFile(path), TYPED_CONFIG_FILE);
    if (!marker || original !== renderVoidConfig(loaded, marker)) {
      throw new Error(
        `config: ${TYPED_CONFIG_FILE} contains authored TypeScript or comments. Update it directly and rerun the command.`,
      );
    }
  }
  writeFileSync(path, renderVoidConfig(config, '// Generated by void init.'));
}
